#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

using std::size_t;

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    size_t q1 = 0;
    size_t q2 = 0;
    size_t q3 = 0;
    size_t q4 = 0;

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(points.size());

    #pragma omp parallel for reduction(+:q1,q2,q3,q4)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        const Point& p = points[static_cast<size_t>(i)];

        if (p.x > 0.0 && p.y > 0.0) {
            ++q1; // Quadrant I
        } else if (p.x < 0.0 && p.y > 0.0) {
            ++q2; // Quadrant II
        } else if (p.x < 0.0 && p.y < 0.0) {
            ++q3; // Quadrant III
        } else if (p.x > 0.0 && p.y < 0.0) {
            ++q4; // Quadrant IV
        }
        // Points on the axes are not counted in any quadrant.
    }

    bins = {q1, q2, q3, q4};
}
